1	// JSON Pointer (RFC 6901) and JSON Patch (RFC 6902).
2	
3	export class PatchError extends Error {
4	  constructor(message, index) {
5	    super(message);
6	    this.name = 'PatchError';
7	    this.index = index;
8	  }
9	}
10	
11	const OPS = new Set(['add', 'remove', 'replace', 'move', 'copy', 'test']);
12	const INDEX_RE = /^(?:0|[1-9][0-9]*)$/;
13	
14	// Thrown internally while applying one operation; turned into a PatchError
15	// that carries the operation's index.
16	class Failure {
17	  constructor(reason) {
18	    this.reason = reason;
19	  }
20	}
21	
22	export function parsePointer(pointer) {
23	  if (typeof pointer !== 'string') throw new TypeError('pointer must be a string');
24	  const tokens = tryParsePointer(pointer);
25	  if (tokens === null) throw new SyntaxError('invalid pointer');
26	  return tokens;
27	}
28	
29	// Returns the decoded tokens, or null when the pointer is invalid.
30	function tryParsePointer(pointer) {
31	  if (pointer === '') return [];
32	  if (pointer[0] !== '/' || /~(?![01])/.test(pointer)) return null;
33	  return pointer
34	    .slice(1)
35	    .split('/')
36	    .map((token) => token.replace(/~[01]/g, (esc) => (esc === '~1' ? '/' : '~')));
37	}
38	
39	function isContainer(value) {
40	  return value !== null && typeof value === 'object';
41	}
42	
43	// Defines an own enumerable member, so names such as "__proto__" stay data.
44	function setMember(obj, name, value) {
45	  Object.defineProperty(obj, name, { value, writable: true, enumerable: true, configurable: true });
46	}
47	
48	// Deep copy of a JSON value; iterative so very deep results cannot overflow the stack.
49	function clone(value) {
50	  if (!isContainer(value)) return value;
51	  const root = Array.isArray(value) ? [] : {};
52	  const stack = [[value, root]];
53	  while (stack.length > 0) {
54	    const [src, dst] = stack.pop();
55	    const copyChild = (child) => {
56	      if (!isContainer(child)) return child;
57	      const copy = Array.isArray(child) ? [] : {};
58	      stack.push([child, copy]);
59	      return copy;
60	    };
61	    if (Array.isArray(src)) {
62	      for (let i = 0; i < src.length; i++) dst.push(copyChild(src[i]));
63	    } else {
64	      for (const name of Object.keys(src)) setMember(dst, name, copyChild(src[name]));
65	    }
66	  }
67	  return root;
68	}
69	
70	function jsonType(value) {
71	  if (value === null) return 'null';
72	  if (Array.isArray(value)) return 'array';
73	  return typeof value;
74	}
75	
76	// JSON equality; iterative for the same reason as clone.
77	function equal(a, b) {
78	  const stack = [[a, b]];
79	  while (stack.length > 0) {
80	    const [x, y] = stack.pop();
81	    const type = jsonType(x);
82	    if (type !== jsonType(y)) return false;
83	    if (type === 'array') {
84	      if (x.length !== y.length) return false;
85	      for (let i = 0; i < x.length; i++) stack.push([x[i], y[i]]);
86	    } else if (type === 'object') {
87	      const names = Object.keys(x);
88	      if (names.length !== Object.keys(y).length) return false;
89	      for (const name of names) {
90	        if (!Object.hasOwn(y, name)) return false;
91	        stack.push([x[name], y[name]]);
92	      }
93	    } else if (x !== y) {
94	      return false;
95	    }
96	  }
97	  return true;
98	}
99	
100	// Returns the array index a token names on `arr`, or throws.
101	function existingIndex(arr, token, notFound) {
102	  if (token === '-') throw new Failure(notFound);
103	  if (!INDEX_RE.test(token)) throw new Failure('bad index');
104	  const index = Number(token);
105	  if (index >= arr.length) throw new Failure(notFound);
106	  return index;
107	}
108	
109	function child(value, token, notFound) {
110	  if (Array.isArray(value)) return value[existingIndex(value, token, notFound)];
111	  if (isContainer(value) && Object.hasOwn(value, token)) return value[token];
112	  throw new Failure(notFound);
113	}
114	
115	function resolve(doc, tokens, notFound) {
116	  let value = doc;
117	  for (const token of tokens) value = child(value, token, notFound);
118	  return value;
119	}
120	
121	function add(doc, tokens, value) {
122	  if (tokens.length === 0) return value;
123	  const parent = resolve(doc, tokens.slice(0, -1), 'path not found');
124	  const last = tokens[tokens.length - 1];
125	  if (Array.isArray(parent)) {
126	    if (last === '-') {
127	      parent.push(value);
128	    } else if (!INDEX_RE.test(last)) {
129	      throw new Failure('bad index');
130	    } else {
131	      const index = Number(last);
132	      if (index > parent.length) throw new Failure('path not found');
133	      parent.splice(index, 0, value);
134	    }
135	  } else if (isContainer(parent)) {
136	    setMember(parent, last, value);
137	  } else {
138	    throw new Failure('path not found');
139	  }
140	  return doc;
141	}
142	
143	// Removes the value `tokens` names (tokens is non-empty) and returns it.
144	function remove(doc, tokens, notFound) {
145	  const parent = resolve(doc, tokens.slice(0, -1), notFound);
146	  const last = tokens[tokens.length - 1];
147	  const removed = child(parent, last, notFound);
148	  if (Array.isArray(parent)) parent.splice(Number(last), 1);
149	  else delete parent[last];
150	  return removed;
151	}
152	
153	function replace(doc, tokens, value) {
154	  if (tokens.length === 0) return value;
155	  const parent = resolve(doc, tokens.slice(0, -1), 'path not found');
156	  const last = tokens[tokens.length - 1];
157	  child(parent, last, 'path not found');
158	  if (Array.isArray(parent)) parent[Number(last)] = value;
159	  else setMember(parent, last, value);
160	  return doc;
161	}
162	
163	function sameTokens(a, b) {
164	  return a.length === b.length && a.every((token, i) => token === b[i]);
165	}
166	
167	function isProperPrefix(prefix, tokens) {
168	  return prefix.length < tokens.length && prefix.every((token, i) => token === tokens[i]);
169	}
170	
171	// Checks one operation against the form rules; returns the parsed form or a reason string.
172	function checkForm(op) {
173	  if (op === null || Array.isArray(op) || typeof op !== 'object') return 'not an object';
174	  if (!Object.hasOwn(op, 'op') || !OPS.has(op.op)) return 'bad op';
175	  const name = op.op;
176	  const path = Object.hasOwn(op, 'path') && typeof op.path === 'string' ? tryParsePointer(op.path) : null;
177	  if (path === null) return 'bad path';
178	  let from = null;
179	  if (name === 'move' || name === 'copy') {
180	    from = Object.hasOwn(op, 'from') && typeof op.from === 'string' ? tryParsePointer(op.from) : null;
181	    if (from === null) return 'bad from';
182	  }
183	  const usesValue = name === 'add' || name === 'replace' || name === 'test';
184	  if (usesValue && !Object.hasOwn(op, 'value')) return 'missing value';
185	  if (name === 'remove' && path.length === 0) return 'cannot remove root';
186	  if (name === 'move' && isProperPrefix(from, path)) return 'cannot move into own child';
187	  return { name, path, from, value: usesValue ? op.value : undefined };
188	}
189	
190	function applyOne(doc, { name, path, from, value }) {
191	  switch (name) {
192	    case 'add':
193	      return add(doc, path, clone(value));
194	    case 'remove':
195	      remove(doc, path, 'path not found');
196	      return doc;
197	    case 'replace':
198	      return replace(doc, path, clone(value));
199	    case 'move': {
200	      resolve(doc, from, 'from not found');
201	      if (sameTokens(from, path)) return doc;
202	      return add(doc, path, remove(doc, from, 'from not found'));
203	    }
204	    case 'copy':
205	      return add(doc, path, clone(resolve(doc, from, 'from not found')));
206	    case 'test':
207	      if (!equal(resolve(doc, path, 'path not found'), value)) throw new Failure('test failed');
208	      return doc;
209	  }
210	}
211	
212	export function applyPatch(doc, patch) {
213	  if (!Array.isArray(patch)) throw new PatchError('patch must be an array', null);
214	  const ops = [];
215	  for (let i = 0; i < patch.length; i++) {
216	    const form = checkForm(Object.hasOwn(patch, i) ? patch[i] : undefined);
217	    if (typeof form === 'string') throw new PatchError(`operation ${i}: ${form}`, i);
218	    ops.push(form);
219	  }
220	  let result = clone(doc);
221	  for (let i = 0; i < ops.length; i++) {
222	    try {
223	      result = applyOne(result, ops[i]);
224	    } catch (err) {
225	      if (err instanceof Failure) throw new PatchError(`operation ${i}: ${err.reason}`, i);
226	      throw err;
227	    }
228	  }
229	  return result;
230	}
